define([],function(){class DriveAdapter{constructor(root){this.root=root;this.handlers={}}play(){return Promise.resolve()}pause(){}getCurrentTime(){return 0}getDuration(){return 0}getPlaybackRate(){return 1}seek(){}onPlay(handler){this.on("play",handler)}onPause(handler){this.on("pause",handler)}onTimeUpdate(handler){this.on("timeupdate",handler)}onSeek(handler){this.on("seek",handler)}onEnded(handler){this.on("ended",handler)}onRateChange(handler){this.on("ratechange",handler)}on(name,handler){this.handlers[name]=(this.handlers[name]||[]).concat(handler)}}const create=root=>Promise.resolve(new DriveAdapter(root));return{create:create}});